import java.io.*;
import java.util.*;

public class E {
    private static final StringBuilder OUT_BUFFER = new StringBuilder(131072);
    private static Scanner SCANNER;

    void solve() throws IOException {
        long n = SCANNER.nextLong();
        long[] A = new long[3];
        long[] B = new long[3];
        for (int i = 0; i < 3; ++i) A[i] = SCANNER.nextLong();
        for (int i = 0; i < 3; ++i) B[i] = SCANNER.nextLong();

        long winCount = 0;
        long nonWinCount = 0;

        for (int idx = 0; idx < 3; ++idx) {
            winCount += Math.min(A[idx], B[(idx + 1) % 3]);
            long possibleDefeat = Math.min(B[idx], A[(idx + 1) % 3]);
            long possibleTie = Math.min(B[idx], A[idx]);
            nonWinCount += Math.min(B[idx], possibleDefeat + possibleTie);
        }

        System.out.print((n - nonWinCount) + " " + winCount + "\n");
    }

    public static void main(String[] args) throws IOException {
        SCANNER = new Scanner(System.in);
        new E().solve();
    }

    static class Scanner {
        private InputStream in;
        private byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        public Scanner(InputStream stream) { in = stream; }

        private boolean hasMoreBytes() {
            if (ptr >= len) {
                ptr = 0;
                try { len = in.read(buffer); } catch (IOException e) { e.printStackTrace(); }
                if (len <= 0) return false;
            }
            return true;
        }

        private int readByte() { return hasMoreBytes() ? buffer[ptr++] : -1; }

        private boolean isSpaceChar(int c) { return c <= 32 || c == 127; }

        private boolean isPrintableChar(int c) { return c >= 33 && c <= 126; }

        public boolean hasNext() {
            while (hasMoreBytes() && !isPrintableChar(buffer[ptr])) ptr++;
            return hasMoreBytes();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int c = readByte();
            while (isPrintableChar(c)) {
                sb.appendCodePoint(c);
                c = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long value = 0;
            boolean negative = false;
            int c = readByte();
            if (c == '-') { negative = true; c = readByte(); }
            if (c < '0' || c > '9') throw new NumberFormatException();
            while (true) {
                if (c >= '0' && c <= '9') {
                    value = value * 10 + (c - '0');
                } else if (c == -1 || !isPrintableChar(c) || c == ':') {
                    return negative ? -value : value;
                } else {
                    throw new NumberFormatException();
                }
                c = readByte();
            }
        }

        public int nextInt() {
            long val = nextLong();
            if (val < Integer.MIN_VALUE || val > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) val;
        }
    }
}
